const EMAIL_PATTERN = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
const MAX_NAME_LENGTH = 80;

export const USER_ROLES = ['owner', 'admin', 'member', 'viewer'];

const valid = (value) => ({ value });
const invalid = (error) => ({ error });

export function parseEmail(raw, { lowercase = true } = {}) {
  const trimmed = typeof raw === 'string' ? raw.trim() : '';
  const email = lowercase ? trimmed.toLowerCase() : trimmed;
  if (email === '') {
    return invalid('email is required');
  }
  if (!EMAIL_PATTERN.test(email)) {
    return invalid('email is invalid');
  }
  return valid(email);
}

export function parseName(raw, { required = true } = {}) {
  const name = typeof raw === 'string' ? raw.trim() : '';
  if (name === '' && required) {
    return invalid('name is required');
  }
  if (name.length > MAX_NAME_LENGTH) {
    return invalid(`name must be at most ${MAX_NAME_LENGTH} characters`);
  }
  return valid(name);
}

export function parseRole(raw, allowedRoles = USER_ROLES) {
  if (!allowedRoles.includes(raw)) {
    return invalid('role is invalid');
  }
  return valid(raw);
}

/**
 * Collects the results of several field parses into one outcome:
 * `{ values, messages }`, where `values` holds the valid fields by name.
 */
export function collectFields(parsedFields) {
  const values = {};
  const messages = [];
  for (const [field, result] of Object.entries(parsedFields)) {
    if (result.error) {
      messages.push(result.error);
    } else {
      values[field] = result.value;
    }
  }
  return { values, messages };
}

